    # ==================== 首页条目 ====================

    def _home_items(self):
        ready = self.write_state.startswith("已写入")
        status_name = "✅ 站点已合并" if ready else "⚠️ 站点未合并"
        if self.error:
            status_name = "❌ " + self.error[:30]
        valid = self.sources + self.manual_sources
        py_seen = len([s for s in valid if s.get("type") == "PY"]) \
            + len([i for i in self.ignored if i.get("type") == "PY"])
        js_seen = len([s for s in valid if s.get("type") == "JS"]) \
            + len([i for i in self.ignored if i.get("type") == "JS"])
        py_ok = len([s for s in valid if s.get("type") == "PY"])
        js_ok = len([s for s in valid if s.get("type") == "JS"])
        guided_counts = {
            t: len([s for s in self.guided if s.get("type") == t])
            for t in self.GUIDED_TYPES
        }
        if not self.sources and self.scan_time:
            status_remarks = "未发现爬虫 · 请按「使用说明」放入文件"
        else:
            status_remarks = "{} 个源 · {}".format(len(self.sources), self.write_state)
        if self._restart_scheduled:
            refresh_remarks = "检测到变更 · 正在自动重启..."
        elif self.hive_changed:
            refresh_remarks = "检测到变更 · 点此立即刷新"
        else:
            refresh_remarks = "重新扫描 · 无变更时秒回"
        tvbox_exists = any(os.path.isfile(p) for p in self._tvbox_config_paths())
        if tvbox_exists:
            py_count = len([s for s in self.sources if s.get("type") == "PY"])
            if py_count == 0:
                # 首页可能先于扫描渲染, 直接从已生成的订阅文件读真实站点数
                try:
                    import json as _json
                    with open(self._tvbox_config_path(), "r", encoding="utf-8") as fh:
                        py_count = len(_json.load(fh).get("sites", []))
                except Exception:
                    py_count = 0
            export_remarks = "已生成 {} 个PY源 · 点此更新并看导入方法".format(py_count)
        else:
            export_remarks = "FongMi/影视壳用 · 点此一键生成订阅"
        return [
            {
                "vod_id": self.HELP_ID,
                "vod_name": "📖 使用说明 (爬虫文件放哪里?)",
                "vod_pic": self._pic_url("folder"),
                "vod_remarks": "首次使用请先点这里",
            },
            {
                "vod_id": self.RESCAN_ID,
                "vod_name": "⚡ 一键扫描并加载",
                "vod_pic": self._pic_url("scan"),
                "vod_remarks": "每次进站自动扫描 · 点此看状态",
            },
            {
                "vod_id": self.REFRESH_ID,
                "vod_name": "🔄 刷新站源列表",
                "vod_pic": self._pic_url("scan"),
                "vod_remarks": refresh_remarks,
            },
            {
                "vod_id": self.STATE_ID,
                "vod_name": "📊 扫描状态",
                "vod_pic": self._pic_url("status"),
                "vod_remarks": "PY 扫{}导{} · JS 扫{}导{} · NODE {} · PHP {} · 订阅 {}".format(
                    py_seen, py_ok, js_seen, js_ok,
                    guided_counts["NODE"], guided_counts["PHP"], guided_counts["SUB"]),
            },
            {
                "vod_id": self.STATUS_ID,
                "vod_name": status_name,
                "vod_pic": self._pic_url("status"),
                "vod_remarks": status_remarks,
            },
            {
                "vod_id": self.CLEAR_ID,
                "vod_name": "🗑 一键清除自动站点",
                "vod_pic": self._pic_url("clear"),
                "vod_remarks": "仅移除本脚本生成的站点, 保留手工项",
            },
            {
                "vod_id": self.EXPORT_TV_ID,
                "vod_name": "📥 导出影视壳配置",
                "vod_pic": self._pic_url("py"),
                "vod_remarks": export_remarks,
            },
        ]

